1	package mevwatch
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"strings"
8		"unicode"
9	)
10	
11	// This file holds the shared structural validation for the single-object
12	// JSON registration documents: rule versions (rules.go) and suppression
13	// conditions (alerts.go). Both must contain exactly one JSON object with
14	// nothing but whitespace around it and with no field declared twice in the
15	// same object; the scan runs before the typed decoder reads any business
16	// value, so strings and numbers are never normalized here.
17	//
18	// The two document families keep their own public wording and sentinel
19	// errors, their own idea of which nested objects carry a field table of
20	// their own, and their own way of detecting content after the closing
21	// brace. Those differences are injected through specPolicy; the tokenizing
22	// machinery below exists once.
23	
24	// specPolicy configures scanJSONObject for one registration document
25	// family.
26	type specPolicy struct {
27		// topObject labels the root object in duplicate-field errors.
28		topObject string
29		// known maps the case-folded spelling of every accepted root field to
30		// its canonical name. Folding matches the decoder's field matching, so
31		// spellings like "ſeverity" (U+017F for s) fold onto "severity".
32		known map[string]string
33		// nested names the known fields whose value is itself an object that
34		// must carry its own per-object duplicate table. Any other object or
35		// array value is consumed without looking inside.
36		nested map[string]nestedObjectSpec
37		// rejectExactUnknown makes an exact re-spelling of even an unknown key
38		// (same bytes after JSON unescaping) a duplicate. Case-only variants of
39		// unknown keys stay undetected here and surface as unknown fields in
40		// the typed decode.
41		rejectExactUnknown bool
42	
43		// firstTokenError reports a failure to read any first token (including
44		// empty input, which surfaces as io.EOF).
45		firstTokenError func(err error) error
46		// nonObject reports a first token that is not an opening brace.
47		nonObject func(tok json.Token) error
48		// wrap prefixes syntax errors found while scanning the object.
49		wrap func(err error) error
50		// duplicate reports a repeated field. For known fields field is the
51		// canonical name; for an exact unknown-key repeat it is the key itself.
52		// first is the earlier spelling, spelling the current one. A nil hook
53		// disables duplicate detection entirely: the scanner then proves shape
54		// (one object, balanced brackets, no trailing content) only.
55		duplicate func(obj, field, first, spelling string) error
56		// trailing reports content after the closing brace, given the raw
57		// document and the byte offset just past it.
58		trailing func(raw []byte, offset int) error
59	}
60	
61	// scanJSONObject proves raw holds exactly one JSON object with no repeated
62	// field in any scanned object and with no content after it beyond what the
63	// policy's trailing check allows. It never interprets values.
64	func scanJSONObject(raw []byte, p specPolicy) error {
65		dec := json.NewDecoder(bytes.NewReader(raw))
66		first, err := dec.Token()
67		if err != nil {
68			return p.firstTokenError(err)
69		}
70		if d, ok := first.(json.Delim); !ok || d != '{' {
71			return p.nonObject(first)
72		}
73		if err := scanObject(dec, p, p.known, p.topObject); err != nil {
74			return err
75		}
76		return p.trailing(raw, int(dec.InputOffset()))
77	}
78	
79	// scanObject consumes one object whose opening brace has already been read
80	// and checks its keys against known. obj names the object for duplicate
81	// errors. Objects named in the policy's nested table are scanned with that
82	// table; every other container is skipped without looking inside.
83	func scanObject(dec *json.Decoder, p specPolicy, known map[string]string, obj string) error {
84		seen := make(map[string]string, len(known))
85		spellings := make(map[string]string)
86		for dec.More() {
87			keyTok, err := dec.Token()
88			if err != nil {
89				return p.wrap(err)
90			}
91			key, ok := keyTok.(string)
92			if !ok {
93				return p.wrap(fmt.Errorf("object key is %s, want string", jsonTokenName(keyTok)))
94			}
95			target, knownKey := known[foldName(key)]
96			if p.duplicate != nil {
97				if p.rejectExactUnknown {
98					// An exact repeat of a decoded key name (known or unknown) is a
99					// duplicate; escapes are decoded first, so "id" == "id".
100					if first, dup := spellings[key]; dup {
101						return p.duplicate(obj, key, first, key)
102					}
103					spellings[key] = key
104				}
105				if knownKey {
106					// Another spelling of the same known field is the same field:
107					// "Severity", "severity" and "ſeverity" cannot share one object.
108					if first, dup := seen[target]; dup {
109						return p.duplicate(obj, target, first, key)
110					}
111					seen[target] = key
112				}
113			}
114			start, err := dec.Token()
115			if err != nil {
116				return p.wrap(err)
117			}
118			if d, isDelim := start.(json.Delim); isDelim {
119				switch d {
120				case '{':
121					nested, hasShape := p.nested[target]
122					if !knownKey || !hasShape {
123						if err := skipContainer(dec, p); err != nil {
124							return err
125						}
126						continue
127					}
128					if err := scanObject(dec, p, nested.fields, nested.label); err != nil {
129						return err
130					}
131				case '[':
132					if err := skipContainer(dec, p); err != nil {
133						return err
134					}
135				}
136				continue
137			}
138		}
139		closeTok, err := dec.Token()
140		if err != nil {
141			return p.wrap(err)
142		}
143		if closeTok != json.Delim('}') {
144			return p.wrap(fmt.Errorf("expected closing brace, got %s", jsonTokenName(closeTok)))
145		}
146		return nil
147	}
148	
149	// skipContainer consumes the remainder of one object or array whose
150	// opening delimiter has already been read, balancing nested brackets. The
151	// scanner itself rejects mismatched brackets, so only depth bookkeeping is
152	// needed here.
153	func skipContainer(dec *json.Decoder, p specPolicy) error {
154		depth := 1
155		for depth > 0 {
156			tok, err := dec.Token()
157			if err != nil {
158				return p.wrap(err)
159			}
160			if d, ok := tok.(json.Delim); ok {
161				switch d {
162				case '{', '[':
163					depth++
164				case '}', ']':
165					depth--
166				}
167			}
168		}
169		return nil
170	}
171	
172	// jsonTokenName describes a token the way the structural error messages do.
173	func jsonTokenName(tok json.Token) string {
174		switch t := tok.(type) {
175		case json.Delim:
176			switch t {
177			case '[':
178				return "array"
179			case '{':
180				return "object"
181			case ']':
182				return "extra closing bracket ']'"
183			case '}':
184				return "extra closing brace '}'"
185			}
186		case nil:
187			return "null"
188		case bool:
189			return "boolean"
190		case string:
191			return "string"
192		case json.Number:
193			return "number"
194		case float64:
195			return "number"
196		case int64:
197			return "number"
198		}
199		return "value"
200	}
201	
202	// trailingTokenName identifies the kind of JSON token started by the first
203	// non-whitespace byte after a closed object.
204	func trailingTokenName(b byte) string {
205		switch b {
206		case '{':
207			return "object"
208		case '[':
209			return "array"
210		case '}':
211			return "extra closing brace '}'"
212		case ']':
213			return "extra closing bracket ']'"
214		case '"':
215			return "string"
216		case 't', 'f':
217			return "boolean"
218		case 'n':
219			return "null"
220		default:
221			if (b >= '0' && b <= '9') || b == '-' {
222				return "number"
223			}
224			return fmt.Sprintf("unexpected character %q", rune(b))
225		}
226	}
227	
228	// fieldTable maps the case-folded spellings of a struct object's JSON
229	// fields to their canonical names. Folding follows the decoder's field
230	// matching (see foldName), not plain lowercasing.
231	func fieldTable(fields ...string) map[string]string {
232		table := make(map[string]string, len(fields))
233		for _, f := range fields {
234			table[foldName(f)] = f
235		}
236		return table
237	}
238	
239	// foldName normalizes a JSON object key the way encoding/json matches
240	// struct field names: every rune is replaced by the smallest rune of its
241	// Unicode simple case-folding orbit. Besides ASCII case this also folds
242	// compatibility spellings the decoder accepts, such as "ſ" (U+017F, Latin
243	// small long s) onto "s" and "K" (U+212A, Kelvin sign) onto "k", so a key
244	// like "ſeverity" names the same field as "severity" here too.
245	func foldName(s string) string {
246		var b strings.Builder
247		b.Grow(len(s))
248		for _, r := range s {
249			b.WriteRune(foldRune(r))
250		}
251		return b.String()
252	}
253	
254	// foldRune returns the smallest rune in r's simple case-folding orbit,
255	// mirroring the fold encoding/json applies to field names.
256	func foldRune(r rune) rune {
257		for {
258			r2 := unicode.SimpleFold(r)
259			if r2 <= r {
260				return r2
261			}
262			r = r2
263		}
264	}
265	
266	// nestedObjectSpec pairs a nested object's field table with the label used
267	// in its duplicate-field errors.
268	type nestedObjectSpec struct {
269		fields map[string]string
270		label  string
271	}
