509	func parseBlocks(r io.Reader) ([]parsedBlock, error) {
510		var out []parsedBlock
511		reader := bufio.NewReader(r)
512		lineNo := 0
513		for {
514			raw, err := reader.ReadBytes('\n')
515			if len(raw) > 0 {
516				lineNo++
517			}
518			if text := strings.TrimSpace(string(raw)); text != "" {
519				block, perr := parseBlock(text)
520				if perr != nil {
521					return nil, &LineError{Line: lineNo, Err: perr}
522				}
523				out = append(out, parsedBlock{line: lineNo, block: block})
524			}
525			if err == io.EOF {
526				return out, nil
527			}
528			if err != nil {
529				return nil, err
530			}
531		}
532	}
