1	package mevwatch
2	
3	// Regression coverage for the historical side of `compare`: when a user
4	// compares an archived block against a candidate rule version, the
5	// declaration the block archived must first pass the exact integrity
6	// proof a `report` query enforces before any comparison is returned. A
7	// legal candidate can never make a damaged historical declaration
8	// participate: a written null used to be explained as the built-in rules
9	// and an incomplete declaration used to compare under silently zeroed
10	// parameters. Only an old-format record with no version key at all keeps
11	// the built-in interpretation. On corruption the whole comparison fails
12	// with ErrCorruptVersion — no partial result, even when the block has no
13	// swaps or an empty findings array. The check is read-only.
14	
15	import (
16		"errors"
17		"os"
18		"path/filepath"
19		"reflect"
20		"strings"
21		"testing"
22	)
23	
24	// assertCompareRefused runs one failing Compare and pins the failure
25	// shape: ErrCorruptVersion wrapping the cause, never an unknown-block or
26	// unknown-version misread, naming the target chain and block plus every
27	// required extra substring, leaving the archive byte-identical.
28	func assertCompareRefused(t *testing.T, dir, chain, hash, candidate string, want ...string) {
29		t.Helper()
30		before := readArchiveFile(t, dir)
31		result, err := Compare(dir, chain, hash, candidate)
32		if err == nil {
33			t.Fatalf("corrupt historical declaration compared successfully: %+v", result)
34		}
35		if !errors.Is(err, ErrCorruptVersion) {
36			t.Fatalf("error = %v, want ErrCorruptVersion", err)
37		}
38		if errors.Is(err, ErrUnknownBlock) || errors.Is(err, ErrUnknownVersion) {
39			t.Fatalf("corrupt historical declaration misreported as unknown block/version: %v", err)
40		}
41		msg := err.Error()
42		for _, sub := range append([]string{chain, hash}, want...) {
43			if !strings.Contains(msg, sub) {
44				t.Fatalf("error %q must name %q", msg, sub)
45			}
46		}
47		if after := readArchiveFile(t, dir); !reflect.DeepEqual(before, after) {
48			t.Fatalf("failed compare changed the archive")
49		}
50		// No partial result is ever returned, and a second attempt fails the
51		// same way: the declaration is not repaired or completed.
52		if _, err := Compare(dir, chain, hash, candidate); !errors.Is(err, ErrCorruptVersion) {
53			t.Fatalf("second compare did not fail the same way: %v", err)
54		}
55	}
56	
57	// TestCompareCorruptSavedVersionRefused runs the full corruption matrix
58	// against the declaration embedded in the compared report (the
59	// registered versions section and the candidate stay intact): every way
60	// the saved document can stop satisfying the registration rules must
61	// fail the whole comparison, naming chain, block, the readable saved id
62	// and the offending rule or field.
63	func TestCompareCorruptSavedVersionRefused(t *testing.T) {
64		for _, tc := range corruptVersionCases {
65			t.Run(tc.name, func(t *testing.T) {
66				dir := setupCorruptCompareArchive(t)
67				rewriteStoredReportVersion(t, dir, "1", "0xblk", func(ver map[string]any) {
68					tc.mutate(t, ver)
69				})
70				// The candidate (twin) is itself intact; its legality must not
71				// rescue the damaged historical declaration.
72				assertCompareRefused(t, dir, "1", "0xblk", "twin", "candC", tc.wantErr)
73			})
74		}
75	}
76	
77	// TestCompareNullAndEmptySavedVersionCorrupt pins the exact misread
78	// being fixed: version:null used to leave the decoded version pointer
79	// nil and be explained as the built-in rules, and {} or an incomplete
80	// object compared under zeroed parameters. All of these fail; only a
81	// wholly missing version key is the legacy built-in shape.
82	func TestCompareNullAndEmptySavedVersionCorrupt(t *testing.T) {
83		cases := []struct {
84			name  string
85			value any
86			// idReachable says whether the error can still name a saved id.
87			idReachable bool
88		}{
89			{"null", nil, false},
90			{"empty object", map[string]any{}, false},
91			{"incomplete object", map[string]any{"id": "candC"}, true},
92			{"non-object number", 5, false},
93			{"non-object string", "builtin", false},
94			{"array", []any{}, false},
95		}
96		for _, tc := range cases {
97			t.Run(tc.name, func(t *testing.T) {
98				dir := setupCorruptCompareArchive(t)
99				replaceStoredReportVersion(t, dir, "1", "0xblk", tc.value)
100				want := []string{}
101				if tc.idReachable {
102					want = append(want, "candC")
103				}
104				assertCompareRefused(t, dir, "1", "0xblk", "twin", want...)
105			})
106		}
107	}
108	
109	// TestCompareBuiltinIDDoesNotBypassValidation proves an id of
110	// "builtin" names the same saved declaration as any other id and is
111	// validated in full rather than substituting the in-code builtin rules.
112	func TestCompareBuiltinIDDoesNotBypassValidation(t *testing.T) {
113		dir := setupCorruptCompareArchive(t)
114	
115		builtinFull := map[string]any{
116			"id": "builtin",
117			"rules": map[string]any{
118				"sandwich":     map[string]any{"enabled": true, "severity": 3},
119				"displacement": map[string]any{"enabled": true, "severity": 2, "multiplier": 2},
120			},
121		}
122		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinFull)
123		result, err := Compare(dir, "1", "0xblk", "twin")
124		if err != nil {
125			t.Fatalf("a complete builtin-id declaration must compare: %v", err)
126		}
127		if result.OriginalVersion != BuiltinVersion() {
128			t.Fatalf("historical side = %+v, want builtin parameters", result.OriginalVersion)
129		}
130	
131		// The same id with a missing field is corrupt and names "builtin"
132		// rather than silently substituting it.
133		builtinDamaged := map[string]any{
134			"id": "builtin",
135			"rules": map[string]any{
136				"sandwich":     map[string]any{"enabled": true, "severity": 3},
137				"displacement": map[string]any{"enabled": true, "severity": 2},
138			},
139		}
140		replaceStoredReportVersion(t, dir, "1", "0xblk", builtinDamaged)
141		assertCompareRefused(t, dir, "1", "0xblk", "twin", BuiltinVersionID, "multiplier")
142	}
143	
144	// TestCompareDuplicateFieldsInSavedVersionRefused covers decay
145	// registration could never have produced: a repeated field in the
146	// saved declaration, including an escaped spelling and a case-only
147	// spelling that name the same field, even when both values agree. The
148	// two rules each declaring their own enabled/severity is not a repeat.
149	func TestCompareDuplicateFieldsInSavedVersionRefused(t *testing.T) {
150		cases := []struct{ name, field string }{
151			{"exact", `"severity": 4, `},
152			{"case variant", `"Severity": 4, `},
153			{"escaped", "\"se\\u0076erity\": 4, "},
154		}
155		for _, dup := range cases {
156			t.Run(dup.name, func(t *testing.T) {
157				dir := setupCorruptCompareArchive(t)
158				path := filepath.Join(dir, archiveFileName)
159				text := string(readArchiveFile(t, dir))
160				versionsAt := strings.Index(text, `"versions":`)
161				if versionsAt < 0 {
162					t.Fatal("versions section not found")
163				}
164				at := strings.Index(text[:versionsAt], `"id": "candC"`)
165				if at < 0 {
166					t.Fatal("record's embedded candC declaration not found")
167				}
168				anchor := `"severity": 4,`
169				field := strings.Index(text[at:versionsAt], anchor)
170				if field < 0 {
171					t.Fatal("severity field not found in embedded declaration")
172				}
173				pos := at + field
174				patched := text[:pos] + dup.field + text[pos:]
175				if err := os.WriteFile(path, []byte(patched), 0o644); err != nil {
176					t.Fatal(err)
177				}
178				result, err := Compare(dir, "1", "0xblk", "twin")
179				if err == nil {
180					t.Fatalf("duplicate-field declaration compared: %+v", result)
181				}
182				if !errors.Is(err, ErrCorruptVersion) || !errors.Is(err, ErrDuplicateField) {
183					t.Fatalf("err = %v, want ErrCorruptVersion wrapping ErrDuplicateField", err)
184				}
185				if !strings.Contains(err.Error(), "candC") || !strings.Contains(err.Error(), "severity") {
186					t.Fatalf("error must name candC and severity, got %v", err)
187				}
188				if after := readArchiveFile(t, dir); after == nil || !strings.Contains(string(after), dup.field) {
189					t.Fatalf("failed compare repaired the duplicate field")
